package dev.jarofcucumbers.prscraft;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import net.minecraft.nbt.CompoundTag;
import java.nio.charset.StandardCharsets;
class SymbolCodebookTest{
 private MessageSettings settings(String text){return new MessageSettings("utf8",text,"raw",1000,0,-1,1,0);}
 @Test void variableLengthUnicodeAndEscapesRoundTripWithoutPaddingSymbols(){var book=SymbolCodebook.parse("А=0\nB=10\n🌍=110\nSPACE=1110\n\\n=11110\nU+003D=11111");var original="АB🌍 =\n".getBytes(StandardCharsets.UTF_8);assertArrayEquals(original,book.decode(book.encode(original)));assertEquals(6,SymbolCodebook.parse(SymbolCodebook.DEFAULT).encode("ABBA".getBytes(StandardCharsets.UTF_8)).bitLength());}
 @Test void rejectsPrefixCollisionsInEitherOrderAndDuplicateSymbols(){for(String mapping:new String[]{"A=001\nB=0011","B=0011\nA=001","A=0\nB=0","A=0\nA=1","U+D800=0","A=2","AA=0","A=",""})assertThrows(IllegalArgumentException.class,()->SymbolCodebook.parse(mapping),mapping);assertDoesNotThrow(()->SymbolCodebook.parse("A=001\nB=0111"));}
 @Test void unknownSymbolsAndTruncatedOrImpossiblePathsFail(){var book=SymbolCodebook.parse("A=00\nB=01");assertThrows(SymbolCodebook.MissingSymbol.class,()->book.encode("C".getBytes(StandardCharsets.UTF_8)));var w=new BitStream.Writer();w.bit(false);assertThrows(IllegalArgumentException.class,()->book.decode(w.finish()));var invalid=new BitStream.Writer();invalid.bit(true);assertThrows(IllegalArgumentException.class,()->book.decode(invalid.finish()));}
 @Test void receiverUsesLocalCardAndNeverInventsTextWithoutOne(){var s=settings("ABBA");var book=SymbolCodebook.parse(SymbolCodebook.DEFAULT);var signal=MessageSignal.source(s,true,1,book);var raw=new CompoundTag();signal.describe(raw,s,true);assertTrue(raw.getBoolean("messageCodebookMissing"));assertFalse(raw.contains("messageText"));assertFalse(raw.getBoolean("messageMatch"));assertEquals(6,raw.getInt("messageWireBits"));var decoded=new CompoundTag();signal.describe(decoded,s,true,book);assertEquals("ABBA",decoded.getString("messageText"));assertTrue(decoded.getBoolean("messageMatch"));var wrong=new CompoundTag();signal.describe(wrong,s,true,SymbolCodebook.parse("C=0\nD=10\nSPACE=11"));assertEquals("CDDC",wrong.getString("messageText"));assertFalse(wrong.getBoolean("messageMatch"));}
 @Test void byteAlignedCustomBitsAlsoRemainRawWithoutACard(){var s=settings("AAAAAAAA");var signal=MessageSignal.source(s,true,1,SymbolCodebook.parse(SymbolCodebook.DEFAULT));var raw=new CompoundTag();signal.describe(raw,s,true);assertEquals(8,raw.getInt("messageWireBits"));assertFalse(raw.getBoolean("messageUtf8"));assertFalse(raw.contains("messageText"));}
 @Test void codecCanEncodeThenDecodeAndRequiresThePhysicalTable(){var s=settings("AB BA");var book=SymbolCodebook.parse(SymbolCodebook.DEFAULT);var encoded=MessageSignal.source(s,true,1).process(s.operation("custom_encode"),"message_codec",book);assertTrue(encoded.customCoded);assertThrows(IllegalArgumentException.class,()->encoded.process(s.operation("custom_decode"),"message_codec"));var decoded=encoded.process(s.operation("custom_decode"),"message_codec",book);assertFalse(decoded.customCoded);assertArrayEquals(s.sourceBytes(),decoded.observed(0).aligned());}
 @Test void entropyIsMeasuredPerUnicodeSymbol(){var t=SymbolCodebook.parse("А=0\nB=10").statistics("АBАB".getBytes(StandardCharsets.UTF_8));assertEquals(1,t.getDouble("entropy"),1e-12);assertEquals(1.5,t.getDouble("averageCodeLength"),1e-12);assertEquals("symbol",t.getString("entropyUnit"));}
}
